def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if g[r][c] == 2 and all(g[rr][cc] == 3 for rr, cc in
                    [(r-1,c-1),(r-1,c),(r-1,c+1),(r,c-1),(r,c+1),
                     (r+1,c-1),(r+1,c),(r+1,c+1)]):
                centers.append((r, c))
    # A marked 3-ring launches a one-cell-wide ray perpendicular to its 2-grid line.
    # When the ray reaches another 2-line, it fans out by one cell around the crossing.
    for r, c in centers:
        row_score = sum(g[r][x] == 2 for x in range(w))
        col_score = sum(g[y][c] == 2 for y in range(h))
        if row_score >= col_score:
            for dr in (-1, 1):
                y = r + dr * 2
                while 0 <= y < h:
                    if g[y][c] == 2:
                        for dc in (-1, 1):
                            x = c + dc
                            if 0 <= x < w and g[y][x] != 3:
                                g[y][x] = 1
                        for yy in (y - 1, y + 1):
                            if 0 <= yy < h and g[yy][c] != 3:
                                g[yy][c] = 1
                    elif g[y][c] != 3:
                        g[y][c] = 1
                    y += dr
        else:
            for dc in (-1, 1):
                x = c + dc * 2
                while 0 <= x < w:
                    if g[r][x] == 2:
                        for dr in (-1, 1):
                            y = r + dr
                            if 0 <= y < h and g[y][x] != 3:
                                g[y][x] = 1
                        for xx in (x - 1, x + 1):
                            if 0 <= xx < w and g[r][xx] != 3:
                                g[r][xx] = 1
                    elif g[r][x] != 3:
                        g[r][x] = 1
                    x += dc
    return g
